import{_ as t,o as a,c as i,ah as n}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Applications","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/secretariat/candidatures.md","filePath":"src/en/guide/secretariat/candidatures.md"}'),o={name:"en/guide/secretariat/candidatures.md"};function s(r,e,l,c,p,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="applications" tabindex="-1">Applications <a class="header-anchor" href="#applications" aria-label="Permalink to &quot;Applications&quot;">​</a></h1><p>The <strong>Applications to review</strong> page lists every application submitted for enrollment, whether it came from the public form filled in by a family (channel <strong>Online</strong>) or was entered by the cashier for a family visiting in person (channel <strong>Cashier</strong>). This is the page where you decide to accept or reject each application.</p><p>Families reach the public form through the <strong>Enrol my child</strong> button on the school&#39;s homepage.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Viewing the queue is always available. Assigning a class (approving an application) depends on the Admissions module being enabled for your school — if the <strong>Approve</strong> button doesn&#39;t appear, contact your administrator.</p></div><h2 id="viewing-the-queue" tabindex="-1">Viewing the queue <a class="header-anchor" href="#viewing-the-queue" aria-label="Permalink to &quot;Viewing the queue&quot;">​</a></h2><p>The page shows, for each application, the student&#39;s name, the desired site, the desired department, the channel, and the status:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Pending</td><td>The application hasn&#39;t been processed yet</td></tr><tr><td>Approved</td><td>The student has been assigned to a class</td></tr><tr><td>Rejected</td><td>The application was rejected, with a reason logged</td></tr></tbody></table><p>Use the search field to find an application by name, and the status filter to show only pending, approved, or rejected applications. Click <strong>Review</strong> on an application&#39;s row to open it.</p><h2 id="reviewing-an-application" tabindex="-1">Reviewing an application <a class="header-anchor" href="#reviewing-an-application" aria-label="Permalink to &quot;Reviewing an application&quot;">​</a></h2><p>The application&#39;s detail page shows you:</p><ul><li>the student&#39;s <strong>date of birth</strong>, desired <strong>site</strong> and <strong>department</strong>, and <strong>channel</strong> (Online or Cashier);</li><li>if the application was entered by the cashier, who <strong>submitted</strong> it;</li><li>the list of <strong>guardians</strong> with their name, email, phone, and relationship; the primary contact carries a <strong>Primary contact</strong> badge;</li><li>the list of <strong>documents</strong> attached to the application, along with who added them (a staff member, or <strong>Submitted online</strong> if the family uploaded them themselves through the public form) — click <strong>Download</strong> to open a document.</li></ul><p>If no documents were attached, the page states this clearly.</p><h2 id="approving-an-application" tabindex="-1">Approving an application <a class="header-anchor" href="#approving-an-application" aria-label="Permalink to &quot;Approving an application&quot;">​</a></h2><ol><li>Open the application from <strong>Review</strong>.</li><li>In the <strong>Assign to a class</strong> section, choose a <strong>class</strong> from the list. Each class shows its current occupancy (for example <code>24/30</code>, or <code>∞</code> if it has no maximum capacity set).</li><li>If the class has reached its capacity, you can&#39;t select it normally: check <strong>Force assignment even if the class has reached its capacity</strong> to assign it anyway.</li><li>Click <strong>Approve</strong>.</li></ol><p>The student is then enrolled in the chosen class, and their financial record becomes visible to the cashier under <strong>Billing</strong> — see <a href="/era-guide/en/guide/caissier/inscriptions-et-paiements.html">Enrollment and payments</a>.</p><h2 id="rejecting-an-application" tabindex="-1">Rejecting an application <a class="header-anchor" href="#rejecting-an-application" aria-label="Permalink to &quot;Rejecting an application&quot;">​</a></h2><ol><li>Open the application from <strong>Review</strong>.</li><li>Click <strong>Reject</strong>.</li><li>In the confirmation window, enter the <strong>Rejection reason</strong> (this field is required).</li><li>Confirm by clicking <strong>Reject</strong> again.</li></ol><p>The rejection reason stays recorded on the application and remains visible afterward.</p>',18)])])}const u=t(o,[["render",s]]);export{g as __pageData,u as default};
